let currentLang = 'en';
try {
  const rawLang = localStorage.getItem('pwa_lang') || MULTI_DECK_DATA.config.defaultLanguage || 'en';
  const cleanLang = rawLang.split('-')[0].toLowerCase();
  currentLang = ['en', 'es', 'de', 'it', 'fr'].includes(cleanLang) ? cleanLang : 'en';
} catch (e) {
  const rawLang = MULTI_DECK_DATA.config.defaultLanguage || 'en';
  const cleanLang = rawLang.split('-')[0].toLowerCase();
  currentLang = ['en', 'es', 'de', 'it', 'fr'].includes(cleanLang) ? cleanLang : 'en';
}
let activeDeck = null;
let drawnCards = [];
let currentSpreadType = 'single';
let currentModalCardIndex = null;

const liveUrl = MULTI_DECK_DATA.config.githubUsername ? `https://${MULTI_DECK_DATA.config.githubUsername}.github.io/${MULTI_DECK_DATA.config.githubRepo}/docs/${MULTI_DECK_DATA.config.slug}/` : window.location.href;

function init() { 
  if (MULTI_DECK_DATA.config.password && sessionStorage.getItem('pwa_gate_unlocked') !== 'true') {
    document.getElementById('gate-screen').classList.remove('hidden');
    document.getElementById('cover-screen').classList.add('hidden');
    document.querySelector('.lang-picker')?.classList.add('hidden');
  } else {
    document.getElementById('gate-screen').classList.add('hidden');
    document.getElementById('cover-screen').classList.remove('hidden');
  }
  updateLanguage(); 
  setupListeners();
  renderDeckCatalog();
  if ('serviceWorker' in navigator && window.location.protocol.startsWith('http')) {
    navigator.serviceWorker.register('service-worker.js', { scope: './' }).catch(err => {
      console.debug('Service Worker register skipped:', err);
    });
  }
}

function updateLanguage() {
    try {
        localStorage.setItem('pwa_lang', currentLang);
    } catch (e) {
        console.debug('localStorage is disabled or blocked in this environment.');
    }
    const t = TRANSLATIONS[currentLang];
    document.querySelectorAll('[data-t]').forEach(el => {
        const key = el.dataset.t;
        const keys = key.split('.');
        let val = t;
        keys.forEach(k => val = val ? val[k] : '');
        el.innerText = val || '';
    });
    document.querySelectorAll('#lang-dropdown button').forEach(btn => {
        if (btn.dataset.lang === currentLang) {
            btn.classList.add('active-lang');
        } else {
            btn.classList.remove('active-lang');
        }
    });
    
    // Update active reading title dynamically
    if (activeDeck) {
        const rTitle = document.getElementById('reading-title');
        if (rTitle && drawnCards.length > 0) {
            const spreadTitleName = t.spreads[currentSpreadType] || t.spreads.single;
            rTitle.innerText = activeDeck.name + ' - ' + spreadTitleName;
        }
    }

    if (drawnCards.length > 0) renderSpread();
    renderDeckCatalog();
    if (currentModalCardIndex !== null) showDetail(currentModalCardIndex);
}

function renderDeckCatalog() {
    const catalog = document.getElementById('deck-catalog-grid');
    if (!catalog) return;
    catalog.innerHTML = '';
    
    MULTI_DECK_DATA.decks.forEach((deck, idx) => {
        const item = document.createElement('div');
        item.className = 'deck-catalog-item';
        item.style.animationDelay = idx * 0.05 + 's';
        item.innerHTML = `
            <div class="deck-catalog-cover-wrapper">
                <img src="${deck.coverImage}" class="deck-catalog-cover" alt="${deck.name}">
                <div class="deck-catalog-badge">${deck.cards.length} ${TRANSLATIONS[currentLang].cardsCount || 'Cards'}</div>
            </div>
            <h3 class="deck-catalog-name">${deck.name}</h3>
        `;
        item.onclick = () => selectDeck(deck);
        catalog.appendChild(item);
    });
}

function selectDeck(deck) {
    activeDeck = deck;
    document.getElementById('catalog-view').classList.add('hidden');
    document.getElementById('deck-view').classList.remove('hidden');
    
    // Update active deck details in UI
    document.getElementById('active-deck-name').innerText = deck.name;
    const backImg = document.querySelector('.deck-back-img');
    if (backImg) backImg.src = deck.backImage;
    
    window.scrollTo(0,0);
}

function selectCatalog() {
    activeDeck = null;
    drawnCards = [];
    document.getElementById('deck-view').classList.add('hidden');
    document.getElementById('reading-view').classList.add('hidden');
    document.getElementById('catalog-view').classList.remove('hidden');
    window.scrollTo(0,0);
}

function setupListeners() {
    const gateSubmit = document.getElementById('gate-submit-btn');
    const gateInput = document.getElementById('gate-password');
    const gateError = document.getElementById('gate-error');
    if (gateSubmit && gateInput) {
        const verifyGate = () => {
            const val = gateInput.value.trim();
            if (val === MULTI_DECK_DATA.config.password) {
                sessionStorage.setItem('pwa_gate_unlocked', 'true');
                document.getElementById('gate-screen').classList.add('hidden');
                document.getElementById('cover-screen').classList.remove('hidden');
                document.querySelector('.lang-picker')?.classList.remove('hidden');
            } else {
                gateError.innerText = 'Incorrect sacred password. Try again.';
                gateError.classList.remove('hidden');
                gateInput.value = '';
                gateInput.focus();
            }
        };
        gateSubmit.onclick = verifyGate;
        gateInput.onkeydown = (e) => {
            if (e.key === 'Enter') verifyGate();
        };
    }

    const shareBtn = document.getElementById('share-btn');
    if (shareBtn) {
        shareBtn.onclick = async () => {
          if (navigator.share) {
            try {
              await navigator.share({
                title: MULTI_DECK_DATA.config.appName,
                text: 'I invite you to explore my sanctuary of sacred oracles.',
                url: liveUrl
              });
            } catch (err) { console.debug('Share failed', err); }
          } else {
            navigator.clipboard.writeText(liveUrl);
            alert('Sacred link copied to clipboard.');
          }
        };
    }
    document.getElementById('lang-toggle').onclick = (e) => { e.stopPropagation(); document.getElementById('lang-dropdown').classList.toggle('hidden'); };
    document.onclick = () => document.getElementById('lang-dropdown').classList.add('hidden');
    document.querySelectorAll('#lang-dropdown button').forEach(btn => {
        btn.onclick = (e) => {
            e.stopPropagation();
            currentLang = btn.dataset.lang;
            updateLanguage();
            document.getElementById('lang-dropdown').classList.add('hidden');
        };
    });
    
    document.getElementById('home-btn').onclick = () => {
        document.getElementById('main-content').classList.add('hidden');
        const cover = document.getElementById('cover-screen');
        cover.style.opacity = '0';
        cover.classList.remove('hidden');
        cover.classList.remove('fade-out');
        setTimeout(() => {
            cover.style.transition = 'opacity 0.5s ease';
            cover.style.opacity = '1';
        }, 10);
        
        document.querySelector('.lang-picker').classList.remove('hidden');
        document.querySelector('.home-picker').classList.add('hidden');
        selectCatalog();
    };
    
    document.getElementById('start-journey-btn').onclick = () => { 
        document.getElementById('cover-screen').classList.add('fade-out'); 
        setTimeout(() => { 
            document.getElementById('cover-screen').classList.add('hidden'); 
            document.getElementById('main-content').classList.remove('hidden'); 
            document.querySelector('.lang-picker').classList.add('hidden');
            document.querySelector('.home-picker').classList.remove('hidden');
        }, 500); 
    };
    
    document.getElementById('back-to-catalog-btn').onclick = () => selectCatalog();
    document.getElementById('back-to-catalog-reading-btn').onclick = () => selectCatalog();
    
    document.querySelectorAll('.spread-btn').forEach(btn => { 
        btn.onclick = () => { 
            currentSpreadType = btn.dataset.type; 
            startReading(currentSpreadType, btn.innerText); 
        }; 
    });
    
    document.getElementById('draw-trigger').onclick = () => { 
        currentSpreadType = 'single'; 
        startReading('single', TRANSLATIONS[currentLang].spreads.single); 
    };
    
    document.getElementById('reset-btn').onclick = () => { 
        document.getElementById('deck-view').classList.remove('hidden'); 
        document.getElementById('reading-view').classList.add('hidden'); 
        drawnCards = []; 
        window.scrollTo(0,0); 
    };
    
    document.querySelector('.close-modal').onclick = () => {
        currentModalCardIndex = null;
        document.getElementById('modal').classList.add('hidden');
    };
    document.getElementById('modal').onclick = (e) => { 
        if(e.target === document.getElementById('modal')) {
            currentModalCardIndex = null;
            document.getElementById('modal').classList.add('hidden'); 
        }
    };
}

function startReading(type, title) {
    if (!activeDeck) return;
    const counts = { single: 1, three_ppf: 3, three_sao: 3, celtic: 10, horseshoe: 7, relationship: 5, decision: 4, year: 12, chakra: 7, career: 6, spiritual: 5, love: 6 };
    const count = counts[type] || 1;
    const shuffled = [...activeDeck.cards].sort(() => Math.random() - 0.5);
    drawnCards = shuffled.slice(0, count);
    document.getElementById('reading-title').innerText = activeDeck.name + ' - ' + title;
    renderSpread();
    document.getElementById('deck-view').classList.add('hidden');
    document.getElementById('reading-view').classList.remove('hidden');
    window.scrollTo(0,0);
}

function getSlotLabel(index, type, lang) {
    const t = TRANSLATIONS[lang];
    if (type === 'three_ppf') return [t.slots.past, t.slots.present, t.slots.future][index];
    if (type === 'three_sao') return [t.slots.situation, t.slots.action, t.slots.outcome][index];
    if (type === 'celtic') return t.slots.celtic[index];
    if (type === 'relationship') return t.slots.relationship[index];
    if (type === 'decision') return t.slots.decision[index];
    if (type === 'year') return t.slots.year[index];
    if (type === 'love') return t.slots.love[index];
    if (type === 'chakra') return t.slots.chakra[index];
    if (type === 'career') return t.slots.career[index];
    if (type === 'spiritual') return t.slots.spiritual[index];
    if (type === 'horseshoe') return t.slots.horseshoe[index];
    return t.slots.card;
}

function renderSpread() {
    const container = document.getElementById('cards-spread');
    container.innerHTML = '';
    drawnCards.forEach((card, idx) => {
        const slotLabel = getSlotLabel(idx, currentSpreadType, currentLang);
        const cardTitle = card.title[currentLang] || card.title['en'] || Object.values(card.title)[0] || '';
        const cardDiv = document.createElement('div');
        cardDiv.className = 'card-item';
        cardDiv.style.animationDelay = idx * 0.15 + 's';
        cardDiv.innerHTML = `
            <div class="slot-label">${slotLabel}</div>
            <div class="card-flip-container">
                <div class="card-flipper">
                    <!-- BACK FACE (Facedown) -->
                    <div class="card-face card-back">
                        <img src="${activeDeck.backImage}" class="card-img" style="object-fit: cover;">
                        <div class="card-back-overlay" style="position:absolute; inset:0; background:rgba(0,0,0,0.35); display:flex; flex-direction:column; align-items:center; justify-content:center; gap:8px;">
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="color:var(--theme-color); opacity:0.8;">
                                <circle cx="12" cy="12" r="1"/>
                                <circle cx="12" cy="5" r="1"/>
                                <circle cx="12" cy="19" r="1"/>
                            </svg>
                            <span style="font-size:0.55rem; font-weight:800; letter-spacing:0.25em; text-transform:uppercase; color:var(--theme-color); opacity:0.8;">Reveal</span>
                        </div>
                    </div>
                    <!-- FRONT FACE (Faceup) -->
                    <div class="card-face card-front">
                        <div class="card-img-container" style="width:100%; height:100%; border:none; border-radius:12px;">
                            <img src="${card.image}" class="card-img">
                            <div class="card-overlay">
                                <h3 class="card-title">${cardTitle}</h3>
                                <button class="detail-btn">${TRANSLATIONS[currentLang].readMeaning}</button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        `;
        const flipper = cardDiv.querySelector('.card-flipper');
        flipper.onclick = () => {
            flipper.classList.add('flipped');
        };
        const detailBtn = cardDiv.querySelector('.detail-btn');
        if (detailBtn) {
            detailBtn.onclick = (e) => {
                e.stopPropagation();
                showDetail(idx);
            };
        }
        container.appendChild(cardDiv);
    });
}

function showDetail(idx) {
    currentModalCardIndex = idx;
    const card = drawnCards[idx];
    const rawMeaning = card.meaning[currentLang] || card.meaning['en'] || Object.values(card.meaning)[0] || '';
    const cardTitle = card.title[currentLang] || card.title['en'] || Object.values(card.title)[0] || '';
    const formatted = rawMeaning.split('\n\n').map(segment => {
        const lines = segment.split('\n');
        const head = lines[0] || '';
        const body = lines.slice(1).join(' ');
        let type = 'path';
        const upperHead = head.toUpperCase();
        if(upperHead.includes('VEIL') || upperHead.includes('VELO') || upperHead.includes('VOILE')) type = 'veil';
        if(upperHead.includes('COSMIC') || upperHead.includes('CÓSMIC') || upperHead.includes('COSMICA') || upperHead.includes('COSMIQUE')) type = 'cosmic';
        if(upperHead.includes('VIBRATION') || upperHead.includes('VIBRACIÓN') || upperHead.includes('VIBRAZIONE')) type = 'vib';
        
        return `<div class="meaning-segment">
            <h4 class="m-head ${type}">${head}</h4>
            <p class="m-body">${body}</p>
        </div>`;
    }).join('');

    document.getElementById('modal-body').innerHTML = `
        <div class="detail-view">
            <img src="${card.image}" class="detail-img">
            <h2 class="detail-title">${cardTitle}</h2>
            <div class="meaning-container">${formatted}</div>
        </div>`;
    document.getElementById('modal').classList.remove('hidden');
}
init();